package com.course.platform.service.impl;

import com.course.platform.common.exception.BusinessException;
import com.course.platform.domain.entity.*;
import com.course.platform.infra.persistence.mapper.*;
import org.junit.jupiter.api.*;
import org.springframework.aop.framework.ProxyFactory;
import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.transaction.interceptor.TransactionInterceptor;
import org.springframework.test.util.ReflectionTestUtils;
import java.math.BigDecimal;
import java.time.*;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 阶梯升级复用原账户和资金事实，下一期与即时审核均保持旧成交价格及来源审计。 */
class CoursePrivateUpgradeTransactionTest {
    CoursePrivateRenewalTransactionTest f;
    CoursePrivateUpgradeService service;
    com.course.platform.domain.dto.CoursePrivatePlanRequest targetConfig;
    @BeforeEach void setup() throws Exception {
        f=new CoursePrivateRenewalTransactionTest();f.setup();
        f.f.f.config.setFamilyCode("COURSE_GROWTH");f.f.f.config.setTierCode("ENTRY");f.f.f.config.setTierRank(1);f.f.f.config.getRules().setMode("TIERED_PRICING");f.snapshot();
        f.f.f.f.jdbc.update("UPDATE course_private_contract_term SET operations_mode='TIERED_PRICING',tier_code='ENTRY',tier_rank=1 WHERE id=?",f.sourceId);
        f.f.f.f.jdbc.update("UPDATE course_private_contract SET operations_mode='TIERED_PRICING'");
        targetConfig=f.f.f.json.readValue(f.f.f.json.writeValueAsString(f.f.f.config),com.course.platform.domain.dto.CoursePrivatePlanRequest.class);targetConfig.setPlanCode("GROWTH");targetConfig.setPlanName("成长档");targetConfig.setTierCode("GROWTH");targetConfig.setTierRank(2);targetConfig.getRules().setFixedPrice(new BigDecimal("5"));targetConfig.getRules().setInitialDepositAmount(new BigDecimal("150"));targetConfig.getRules().setValidityDays(60);targetConfig.getRules().setRenewalConsumptionTarget(new BigDecimal("30"));
        var plan=new CoursePrivatePlan();plan.setId(2L);plan.setPlatformId(9L);plan.setPlanCode("GROWTH");plan.setPlanName("成长档");plan.setMode("TIERED_PRICING");plan.setFamilyCode("COURSE_GROWTH");plan.setTierCode("GROWTH");plan.setTierRank(2);plan.setVisibleToAgents(true);plan.setApplicationMode("REVIEW");plan.setStatus("PUBLISHED");plan.setCurrentVersionId(2L);plan.setDraftVersion(1);f.f.f.plans.insert(plan);
        var version=new CoursePrivatePlanVersion();org.springframework.beans.BeanUtils.copyProperties(targetConfig.getRules(),version);version.setId(2L);version.setPlanId(2L);version.setPlatformId(9L);version.setVersionNo(1);version.setPublishedAt(LocalDateTime.now(f.f.f.clock).minusDays(1));version.setConfigSnapshot(f.f.f.json.writeValueAsString(targetConfig));f.f.f.versions.insert(version);
        var authorities=mock(UserAuthorityMapper.class);when(authorities.findAuthoritiesByUserId(8L)).thenReturn(List.of("course-private-contract:review","course-private-term:adjust","course-private-settlement:execute"));
        var target=new CoursePrivateUpgradeService(f.f.f.f.users,f.f.f.products,mock(PlatformCategoryMapper.class),f.f.f.f.contracts,f.f.f.f.wallets,f.f.f.plans,f.f.f.versions,f.f.f.applications,f.f.f.terms,f.f.f.allocations,f.f.f.events,new CoursePrivateOperationsAccess(f.f.f.f.users,authorities),f.f.f.json,new CoursePrivateOperationsTime(f.f.f.clock));
        ReflectionTestUtils.setField(target,"enabled",true);ReflectionTestUtils.setField(target,"settlement",f.f.service);var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.f.f.f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));service=(CoursePrivateUpgradeService)proxy.getProxy();
        ReflectionTestUtils.setField(f.f.f.service,"upgrade",service);
    }
    @AfterEach void clear(){f.clear();}
    Long application(String policy){var app=f.f.f.applications.selectById(1L);app.setId(null);app.setPlanId(2L);app.setVersionId(2L);app.setContractId(f.source().getContractId());app.setSourceTermId(f.sourceId);app.setRequestKey("upgrade_"+policy);app.setApplicationType("UPGRADE");app.setEffectivePolicy(policy);app.setStatus("PENDING");app.setReviewedAt(null);app.setReviewedBy(null);app.setVersion(0);f.f.f.applications.insert(app);return app.getId();}
    void auth(){org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(8L,null,List.of("course-private-contract:review","course-private-term:adjust","course-private-settlement:execute").stream().map(org.springframework.security.core.authority.SimpleGrantedAuthority::new).toList()));}
    CoursePrivateContractTerm review(Long app){auth();return service.review(app,0,8L,"审核同商品成长档，按冻结政策认定资金资格");}
    void deposit(){f.f.f.deposit("50","upgrade_funds");}
    @Test void differenceFundingSchedulesOneNextAndPreservesOriginalPriceUntilBoundary(){deposit();Long app=application("NEXT_TERM");var next=review(app);assertEquals("SCHEDULED",next.getStatus());assertEquals("UPGRADE_FUNDS",next.getQualificationKind());assertEquals(f.source().getEndAt(),next.getStartAt());f.f.f.f.money("5",next.getEffectiveFixedPrice());f.f.f.f.money("7.20",f.f.f.f.contracts.selectByBinding(7L,9L).getFixedPrice());f.f.f.f.money("150",f.f.f.wallet().getBalance());assertEquals(next.getId(),review(app).getId());f.f.f.clock.advance(Duration.ofDays(30));assertEquals("ACTIVE",service.activateScheduled(next.getId()).getStatus());assertEquals(next.getId(),f.f.f.service.effectiveTerm(7L,9L,true).getId());f.f.f.f.money("150",f.f.f.current().getQualificationBasisAmount());}
    @Test void existingBalanceDoesNotSatisfyDifferenceWithoutNewTransfer(){Long app=application("NEXT_TERM");assertThrows(BusinessException.class,()->review(app));assertEquals("PENDING",f.f.f.applications.selectById(app).getStatus());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));f.f.f.f.money("100",f.f.f.wallet().getBalance());}
    @Test void financeReleaseBeforeStartInvalidatesUpgradeAndNewTransferCanRequalify(){deposit();var next=review(application("NEXT_TERM"));f.f.f.auth(8);f.f.f.f.tx.executeWithoutResult(tx->f.f.f.f.service.release(f.f.f.wallet().getId(),8L,f.f.f.f.request("50","before_upgrade")));f.f.f.clock.advance(Duration.ofDays(30));assertNull(service.activateScheduled(next.getId()));assertThrows(BusinessException.class,()->f.f.buy("lost_upgrade"));f.f.f.deposit("50","replace_upgrade");var active=service.activateScheduled(next.getId());assertEquals("ACTIVE",active.getStatus());assertEquals(next.getStartAt(),active.getStartAt());assertEquals(next.getEndAt(),active.getEndAt());}
    @Test void instantUpgradeNeedsExplicitSourcePolicyAndAdditionalPermissions() throws Exception {deposit();Long app=application("REVIEW_IMMEDIATE");assertThrows(BusinessException.class,()->review(app));f.f.f.config.getRules().setUpgradePolicy("REVIEW_IMMEDIATE");f.snapshot();f.f.f.auth(8);assertThrows(BusinessException.class,()->service.review(app,0,8L,"普通审核者不能即时升级"));assertEquals("PENDING",f.f.f.applications.selectById(app).getStatus());}
    @Test void verifiedInstantUpgradeUsesNewPriceAndKeepsOriginalOrderSnapshot() throws Exception {f.f.f.config.getRules().setUpgradePolicy("REVIEW_IMMEDIATE");f.snapshot();Long old=f.f.buy("before_upgrade");f.f.f.clock.advance(Duration.ofSeconds(1));deposit();var before=f.source();var next=review(application("REVIEW_IMMEDIATE"));assertEquals("ACTIVE",next.getStatus());assertEquals(LocalDateTime.now(f.f.f.clock),next.getStartAt());assertEquals("SUPERSEDED",f.source().getStatus());assertEquals(next.getStartAt(),f.source().getSupersededAt());assertEquals(before.getEndAt(),f.source().getEndAt());f.f.f.f.money("7.20",f.f.f.orderRows.selectById(old).getAmount());assertEquals(f.sourceId,f.f.f.orderRows.selectById(old).getPrivateTermId());Long newer=f.f.buy("after_upgrade");f.f.f.f.money("5",f.f.f.orderRows.selectById(newer).getAmount());assertEquals(next.getId(),f.f.f.orderRows.selectById(newer).getPrivateTermId());}
    @Test void alreadyClaimedRenewalFundsCannotAlsoQualifyUpgrade(){deposit();var ledger=f.f.f.allocations.selectUnallocatedTransferIn(f.f.f.wallet().getId(),7L,null,null,null,null).get(0);var claim=new CoursePrivateFundingAllocation();claim.setTermId(f.sourceId);claim.setWalletId(f.f.f.wallet().getId());claim.setUserId(7L);claim.setLedgerId(ledger.getId());claim.setAmount(ledger.getAmount());f.f.f.allocations.insert(claim);assertThrows(BusinessException.class,()->review(application("NEXT_TERM")));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void automaticRenewalAndReviewedUpgradeCannotCreateTwoNextPeriods() throws Exception {f.qualify();deposit();f.f.f.clock.advance(Duration.ofDays(24));Long app=application("NEXT_TERM");var outcomes=f.f.f.f.concurrent(f::renew,()->review(app));assertTrue(outcomes.stream().filter(RuntimeException.class::isInstance).count()<=1);assertEquals(2,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term WHERE renewal_source_term_id=?",Integer.class,f.sourceId));}
    @Test void failedAuditRollsBackQualificationClaimAndApproval(){deposit();Long app=application("NEXT_TERM");f.f.f.f.jdbc.execute("ALTER TABLE course_private_term_event ADD CONSTRAINT reject_upgrade CHECK(event_type NOT LIKE 'UPGRADE%')");assertThrows(RuntimeException.class,()->review(app));assertEquals("PENDING",f.f.f.applications.selectById(app).getStatus());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void relationGenerationOrWrongFamilyCannotUpgrade() throws Exception {deposit();targetConfig.setFamilyCode("OTHER");f.f.f.f.jdbc.update("UPDATE course_private_plan_version SET config_snapshot=? WHERE id=2",f.f.f.json.writeValueAsString(targetConfig));assertThrows(BusinessException.class,()->review(application("NEXT_TERM")));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void fullTargetPolicyRequiresTheWholeTargetFromNewUnclaimedFunds() throws Exception {f.f.f.config.getRules().setUpgradeDepositPolicy("FULL_TARGET");f.snapshot();deposit();Long app=application("NEXT_TERM");assertThrows(BusinessException.class,()->review(app));f.f.f.deposit("100","full_target");var next=review(app);f.f.f.f.money("150",next.getQualifiedDepositAmount());f.f.f.f.money("150",next.getQualificationBasisAmount());assertEquals(3,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));f.f.f.f.money("250",f.f.f.wallet().getBalance());}
    @Test void explicitExistingBalancePolicyUsesBalanceWithoutClaimingItAsNewFunds() throws Exception {f.f.f.config.getRules().setUpgradeDepositPolicy("EXISTING_BALANCE");f.snapshot();Long app=application("NEXT_TERM");assertThrows(BusinessException.class,()->review(app));deposit();var next=review(app);f.f.f.f.money("150",next.getQualifiedDepositAmount());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));}
    @Test void oldRelationGenerationCannotUpgrade(){deposit();Long app=application("NEXT_TERM");f.f.f.f.jdbc.update("UPDATE course_private_contract SET relation_generation=2");assertThrows(BusinessException.class,()->review(app));assertEquals("PENDING",f.f.f.applications.selectById(app).getStatus());}
    void automatic() throws Exception {f.f.f.config.getRules().setUpgradeAuto(true);f.snapshot();ReflectionTestUtils.setField(service,"automaticEnabled",true);}
    @Test void automaticUpgradeRequiresBothIndependentFlagAndFrozenConsent() throws Exception {deposit();assertNull(service.upgradeAutomatic(f.sourceId));ReflectionTestUtils.setField(service,"automaticEnabled",true);assertNull(service.upgradeAutomatic(f.sourceId));automatic();var next=service.upgradeAutomatic(f.sourceId);assertEquals("UPGRADE_FUNDS",next.getQualificationKind());assertEquals("SCHEDULED",next.getStatus());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_application WHERE application_type='UPGRADE' AND status='APPROVED'",Integer.class));}
    @Test void automaticUpgradeDoesNotTreatBalanceAsNewFunds() throws Exception {automatic();assertNull(service.upgradeAutomatic(f.sourceId));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void duplicateAutomaticWorkersDoNotProduceMoreTermsOrApplications() throws Exception {automatic();deposit();var outcomes=f.f.f.f.concurrent(()->service.upgradeAutomatic(f.sourceId),()->service.upgradeAutomatic(f.sourceId));assertEquals(0,outcomes.stream().filter(RuntimeException.class::isInstance).count());assertEquals(2,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_application WHERE application_type='UPGRADE'",Integer.class));}
    @Test void hiddenOrStoppedTargetCannotBeAutoAssigned() throws Exception {automatic();deposit();f.f.f.f.jdbc.update("UPDATE course_private_plan SET visible_to_agents=FALSE WHERE id=2");assertNull(service.upgradeAutomatic(f.sourceId));f.f.f.f.jdbc.update("UPDATE course_private_plan SET visible_to_agents=TRUE,status='DISABLED' WHERE id=2");assertNull(service.upgradeAutomatic(f.sourceId));}
    @Test void tierSelectionUsesPublishedSnapshotRatherThanEditedDraftMetadata() throws Exception {automatic();deposit();f.f.f.f.jdbc.update("UPDATE course_private_plan SET family_code='WRONG_DRAFT',tier_rank=0 WHERE id=2");var next=service.upgradeAutomatic(f.sourceId);assertEquals("GROWTH",next.getTierCode());assertEquals(2,next.getTierRank());}
    @Test void ambiguousEligiblePublishedTierRequiresHumanChoice() throws Exception {automatic();deposit();var plan=new CoursePrivatePlan();org.springframework.beans.BeanUtils.copyProperties(f.f.f.plans.selectById(2L),plan);plan.setId(3L);plan.setPlanCode("GROWTH_ALT");plan.setCurrentVersionId(3L);f.f.f.plans.insert(plan);var version=new CoursePrivatePlanVersion();org.springframework.beans.BeanUtils.copyProperties(f.f.f.versions.selectById(2L),version);version.setId(3L);version.setPlanId(3L);f.f.f.versions.insert(version);assertThrows(BusinessException.class,()->service.upgradeAutomatic(f.sourceId));assertEquals(0,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_application WHERE application_type='UPGRADE'",Integer.class));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));}
    @Test void backgroundWorkerPrioritizesConsentedUpgradeWithoutCreatingOrdinaryRenewal() throws Exception {automatic();f.qualify();deposit();f.f.f.clock.advance(Duration.ofDays(24));var batch=mock(CoursePrivateContractTermMapper.class);when(batch.selectReconciliationBatch(0L,100)).thenReturn(List.of(f.source()));when(batch.selectById(any())).thenAnswer(a->f.f.f.terms.selectById(a.getArgument(0)));when(batch.selectByRenewalSource(any())).thenAnswer(a->f.f.f.terms.selectByRenewalSource(a.getArgument(0)));var worker=new CoursePrivateOperationsWorker(batch,f.f.f.f.wallets,f.f.f.service,f.f.service,new CoursePrivateOperationsTime(f.f.f.clock));ReflectionTestUtils.setField(worker,"enabled",true);ReflectionTestUtils.setField(worker,"renewal",f.service);ReflectionTestUtils.setField(worker,"upgrade",service);worker.reconcile();var next=f.f.f.terms.selectByRenewalSource(f.sourceId);assertEquals("UPGRADE_FUNDS",next.getQualificationKind());assertEquals(2L,next.getVersionId());assertEquals(2,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void legacyConversionUsesConfirmedApplicationWatermarkAndKeepsWalletAndOldOrders() throws Exception {Long old=f.f.buy("legacy_purchase");Long wallet=f.f.f.wallet().getId();f.f.f.f.jdbc.update("UPDATE course_order SET private_term_id=NULL,private_term_version=NULL,private_plan_version_id=NULL,private_operations_mode=NULL WHERE id=?",old);f.f.f.f.jdbc.update("DELETE FROM course_private_term_order WHERE order_id=?",old);f.f.f.f.jdbc.update("UPDATE course_private_contract_term SET operations_mode='LEGACY_PERMANENT',qualification_kind='LEGACY_UNKNOWN',qualification_basis_amount=0,config_snapshot='{}' WHERE id=?",f.sourceId);f.f.f.f.jdbc.update("UPDATE course_private_contract SET operations_mode='LEGACY_PERMANENT'");targetConfig.getRules().setUpgradePolicy("REVIEW_IMMEDIATE");f.f.f.f.jdbc.update("UPDATE course_private_plan_version SET config_snapshot=? WHERE id=2",f.f.f.json.writeValueAsString(targetConfig));Long app=application("REVIEW_IMMEDIATE");f.f.f.f.jdbc.update("UPDATE course_private_application SET acknowledge_legacy_change=TRUE,funding_start_ledger_id=? WHERE id=?",f.f.f.allocations.selectWalletLedgerWatermark(wallet,7L),app);assertThrows(BusinessException.class,()->review(app));f.f.f.deposit("150","legacy_new_funds");f.f.f.f.jdbc.update("UPDATE course_private_application SET submitted_by=8 WHERE id=?",app);var denied=assertThrows(BusinessException.class,()->review(app));assertTrue(denied.getMessage().contains("代理本人"));f.f.f.f.jdbc.update("UPDATE course_private_application SET submitted_by=7 WHERE id=?",app);var next=review(app);assertEquals("ACTIVE",next.getStatus());assertEquals(wallet,f.f.f.wallet().getId());assertNull(f.f.f.orderRows.selectById(old).getPrivateTermId());var oldOrder=f.f.f.orderRows.selectById(old);f.f.f.f.tx.executeWithoutResult(tx->{f.f.f.f.service.refund(oldOrder,8L);f.f.f.orderRows.markRefunded(old);});f.f.f.f.money("250",f.f.f.wallet().getBalance());assertEquals(f.sourceId,f.f.f.events.selectByBizNo("upgrade_activate_"+next.getId()).getSourceTermId());assertEquals("LEGACY_PERMANENT",f.source().getOperationsMode());assertEquals("SUPERSEDED",f.source().getStatus());f.f.f.f.money("7.20",f.f.f.orderRows.selectById(old).getAmount());assertEquals(2,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
}
